WITH customer_returns AS ( SELECT c.c_customer_sk, c.c_first_name, c.c_last_name, ca.ca_country, cd.cd_gender, SUM(wr.wr_return_amt) AS total_return_amt, AVG(wr.wr_return_amt) AS avg_return_amt FROM web_returns wr JOIN customer c ON wr.wr_refunded_customer_sk = c.c_customer_sk JOIN customer_demographics cd ON wr.wr_refunded_cdemo_sk = cd.cd_demo_sk JOIN customer_address ca ON wr.wr_refunded_addr_sk = ca.ca_address_sk GROUP BY c.c_customer_sk, c.c_first_name, c.c_last_name, ca.ca_country, cd.cd_gender ) SELECT cr.c_customer_sk, cr.c_first_name, cr.c_last_name, cr.ca_country, cr.cd_gender, cr.total_return_amt, cr.avg_return_amt, CASE WHEN cr.avg_return_amt > 200 THEN 'Expensive Returns' ELSE 'Standard Returns' END AS avg_return_category, SUM(cr.total_return_amt) OVER (PARTITION BY cr.ca_country ORDER BY cr.total_return_amt DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_country_return FROM customer_returns cr ORDER BY cr.avg_return_amt DESC LIMIT 75
